export const Rulesets: {[k: string]: ModdedFormatData} = {
	wildalpha: {
		effectType: 'Rule',
		name: 'Wild Alpha',
		desc: "Cobblemon Wild Alpha rule.",
		onBegin() { this.add('rule', 'Wild Alpha: The first Pokémon on the opposing side receives an alpha boost.'); },
		onSwitchIn(pokemon) {
			if (pokemon === this.sides[1].active[0])
				pokemon.addVolatile('alphaboost');
		},
	},
};